				if (dn.includes(target) || target.includes(dn)) return true;
				if (target.includes("cac") && dn.includes("cac")) return true;
				if ((target.includes("tax") || target.includes("tcc")) && (dn.includes("tax") || dn.includes("tcc"))) return true;
				if (target.includes("pencom") && dn.includes("pencom")) return true;
				if ((target.includes("dpr") || target.includes("nuprc")) && (dn.includes("dpr") || dn.includes("nuprc"))) return true;
				if ((target.includes("swatch") || target.includes("origin")) && (dn.includes("swatch") || dn.includes("origin"))) return true;
